<template>
	<section class="signing-dashboard">
		<header><div><h2>{{ t('libresign','Dashboard') }}</h2><p>{{ t('libresign','Your signing tasks, requests and campaign documents in one place.') }}</p></div><div class="dashboard-header-actions"><NcButton v-if="canRequest" :to="{name:'requestFiles'}" variant="primary">{{ t('libresign','Request Signature') }}</NcButton><NcButton v-if="canCampaign" :to="{name:'campaign'}">{{ t('libresign','Create Campaign') }}</NcButton><NcButton :disabled="loading" @click="refresh">{{ t('libresign','Refresh') }}</NcButton></div></header>
		<div v-if="error" class="dashboard-error" role="alert"><strong>{{ error }}</strong></div>
		<div class="dashboard-metrics"><button v-for="card in cards" :key="card.key" type="button" :aria-pressed="view===card.key" :disabled="loading" @click="selectView(card.key)"><NcIconSvgWrapper :path="card.icon" :size="24" /><strong>{{ data ? data.counts[card.key] : '—' }}</strong><small class="dashboard-direction">{{ card.direction }}</small><span>{{ card.label }}</span></button></div>
		<section class="dashboard-inbox"><div class="dashboard-inbox__heading"><div><h3>{{ currentCard.label }}</h3><p>{{ descriptions[view] }}</p></div><NcButton :to="{name:'fileslist'}" variant="secondary">{{ t('libresign','Open All Files') }} →</NcButton></div>
			<p v-if="loading" role="status">{{ t('libresign','Loading your documents…') }}</p>
			<div v-else-if="data?.documents.length" class="dashboard-table"><table><thead><tr><th>{{ t('libresign','Document') }}</th><th>{{ t('libresign','Sender') }}</th><th>{{ t('libresign','Date Requested') }}</th><th>{{ t('libresign','Status') }}</th><th>{{ t('libresign','Action') }}</th></tr></thead><tbody><tr v-for="document in data.documents" :key="document.id"><td><strong>{{ document.name }}</strong><small v-if="document.campaign" class="dashboard-campaign">{{ t('libresign','Campaign') }} · {{ document.campaign }}</small><small v-if="document.deadline">{{ t('libresign','Deadline') }}: {{ campaignDate(document.deadline) }}</small></td><td>{{ document.sender }}</td><td>{{ campaignDate(document.requestedAt) }}</td><td><span class="dashboard-status">{{ documentStatus(document) }}</span></td><td><RouterLink class="dashboard-action" :to="{path:'/f/validation/'+document.uuid}">{{ view==='ready' ? t('libresign','Review & sign') : t('libresign','View document') }} →</RouterLink></td></tr></tbody></table></div>
			<div v-else-if="!error" class="dashboard-empty"><NcIconSvgWrapper :path="mdiCheckCircleOutline" :size="36" /><h4>{{ t('libresign','No documents in this view') }}</h4><p>{{ view==='ready' ? t('libresign','You are all caught up. New requests will appear here, including individual campaign copies.') : t('libresign','Use the cards above to see your other signing activity.') }}</p></div>
			<div v-if="data && data.total > data.perPage" class="dashboard-pagination"><NcButton :disabled="loading || page===1" @click="changePage(-1)">{{ t('libresign','Previous') }}</NcButton><span>{{ page }} / {{ Math.ceil(data.total / data.perPage) }}</span><NcButton :disabled="loading || page*data.perPage>=data.total" @click="changePage(1)">{{ t('libresign','Next') }}</NcButton></div>
			<footer class="dashboard-inbox__footer"><span>{{ t('libresign','Showing up to 10 documents per page') }}</span><NcButton :to="{name:'fileslist'}" variant="secondary">{{ t('libresign','Open All Files') }} →</NcButton></footer>
		</section>
		<section class="dashboard-shortcuts"><h3>{{ t('libresign','Quick access') }}</h3><div><RouterLink v-if="canRequest" :to="{name:'requestFiles'}"><NcIconSvgWrapper :path="mdiFileSign" :size="24" /><strong>{{ t('libresign','Request signatures') }}</strong><span>{{ t('libresign','Upload a document and choose its signers.') }}</span></RouterLink><RouterLink v-if="canCampaign" :to="{name:'campaign'}"><NcIconSvgWrapper :path="mdiAccountGroupOutline" :size="24" /><strong>{{ t('libresign','Manage campaigns') }}</strong><span>{{ t('libresign','Prepare documents and track recipient completion.') }}</span></RouterLink><RouterLink :to="{name:'validation'}"><NcIconSvgWrapper :path="mdiShieldCheckOutline" :size="24" /><strong>{{ t('libresign','Verify a document') }}</strong><span>{{ t('libresign','Check a signed document and its signing history.') }}</span></RouterLink><RouterLink v-if="isAdmin" :to="{name:'organisationalArchive'}"><NcIconSvgWrapper :path="mdiArchiveOutline" :size="24" /><strong>{{ t('libresign','Signed Archive') }}</strong><span>{{ t('libresign','Review the protected organisational signing record.') }}</span></RouterLink></div></section>
	</section>
</template>
<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue'
import {RouterLink} from 'vue-router'
import {t} from '@nextcloud/l10n'
import {loadState} from '@nextcloud/initial-state'
import {getCurrentUser} from '@nextcloud/auth'
import {mdiFileSign,mdiCheckCircleOutline,mdiSendOutline,mdiAccountGroupOutline,mdiShieldCheckOutline,mdiArchiveOutline} from '@mdi/js'
import NcButton from '@nextcloud/vue/components/NcButton'
import NcIconSvgWrapper from '@nextcloud/vue/components/NcIconSvgWrapper'
import {campaignGet,campaignDate,campaignError} from '../services/campaigns'
type View='ready'|'signed'|'sent'|'completed'
type Document={id:number,uuid:string,name:string,status:number,sender:string,requestedAt:string,completedAt:string|null,campaign:string|null,deadline:number|null}
type Dashboard={counts:Record<View,number>,documents:Document[],total:number,perPage:number}
const data=ref<Dashboard|null>(null),view=ref<View>('ready'),page=ref(1),loading=ref(false),error=ref(''),canCampaign=ref(false)
const canRequest=loadState('libresign','can_request_sign',false),isAdmin=Boolean(getCurrentUser()?.isAdmin)
const cards=[{key:'ready' as View,direction:t('libresign','Inbound'),label:t('libresign','Awaiting my Signature'),icon:mdiFileSign},{key:'signed' as View,direction:t('libresign','Inbound'),label:t('libresign','Signed by Me'),icon:mdiCheckCircleOutline},{key:'sent' as View,direction:t('libresign','Outbound'),label:t('libresign','Awaiting Completion'),icon:mdiSendOutline},{key:'completed' as View,direction:t('libresign','Outbound'),label:t('libresign','Signing Completed'),icon:mdiCheckCircleOutline}]
const descriptions:Record<View,string>={ready:t('libresign','These documents are ready for you to review and sign. Campaign and individual requests appear together.'),signed:t('libresign','Documents you have signed. Other participants may still need to complete their signatures.'),sent:t('libresign','Requests you sent that have not yet been fully signed, including individual campaign copies.'),completed:t('libresign','Requests you sent where every required signature has been completed.')}
const currentCard=computed(()=>cards.find(card=>card.key===view.value)!)
function documentStatus(document:Document){return view.value==='ready'?t('libresign','Ready to sign'):document.status===3?t('libresign','Completed'):view.value==='signed'?t('libresign','Your signature recorded'):document.status===2?t('libresign','Partially signed'):t('libresign','Awaiting signatures')}
let disposed=false,timer:ReturnType<typeof setInterval>|undefined
async function refresh(){if(loading.value)return;loading.value=true;error.value='';try{const result=await campaignGet<Dashboard>('dashboard',{view:view.value,page:page.value});if(!disposed)data.value=result}catch(e){if(!disposed){data.value=null;error.value=campaignError(e)}}finally{loading.value=false}}
async function selectView(next:View){view.value=next;page.value=1;await refresh()}
async function changePage(delta:number){page.value+=delta;await refresh()}
onMounted(async()=>{await refresh();try{canCampaign.value=(await campaignGet<{canCreate:boolean}>('campaign/access')).canCreate}catch{canCampaign.value=false}if(!disposed)timer=setInterval(()=>{if(!globalThis.document.hidden)void refresh()},600000)})
onBeforeUnmount(()=>{disposed=true;clearInterval(timer)})
</script>
<style scoped lang="scss">
.signing-dashboard{width:100%;box-sizing:border-box;padding:32px clamp(16px,3vw,48px);overflow-y:auto;}header{display:flex;align-items:start;justify-content:space-between;gap:20px;margin-bottom:28px;}h2{font-size:28px;font-weight:650;margin-bottom:8px;}header p,.dashboard-inbox__heading p{color:var(--color-text-maxcontrast);line-height:1.5;}h3{font-size:19px;font-weight:650;margin-bottom:8px;}
.dashboard-header-actions{flex-shrink:0;max-width:100%;display:flex;flex-wrap:wrap;gap:10px;justify-content:flex-end;}.dashboard-inbox__footer{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-top:24px;padding-top:20px;border-top:1px solid var(--color-border);}.dashboard-inbox__footer>span{color:var(--color-text-maxcontrast);font-size:13px;}
.dashboard-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:24px;}.dashboard-metrics button{display:grid;grid-template-columns:1fr auto;align-items:start;gap:14px;height:auto;min-height:136px;margin:0;padding:20px;text-align:start;background:var(--color-main-background);border:1px solid var(--color-border);border-radius:14px;color:var(--color-main-text);}.dashboard-metrics button[aria-pressed=true]{border-color:var(--color-primary-element);box-shadow:inset 0 0 0 1px var(--color-primary-element);background:var(--color-primary-element-light);}.dashboard-metrics strong{font-size:32px;line-height:1;}.dashboard-metrics .dashboard-direction{grid-column:1/-1;font-size:12px;font-weight:650;text-transform:uppercase;letter-spacing:.08em;margin:0;color:var(--color-text-maxcontrast);}.dashboard-metrics span:last-child{margin-top:-6px;}.dashboard-metrics span:last-child{grid-column:1/-1;font-size:14px;font-weight:550;white-space:normal;}
.dashboard-inbox{border:1px solid var(--color-border);border-radius:16px;padding:24px;}.dashboard-inbox__heading{display:flex;justify-content:space-between;gap:20px;align-items:start;margin-bottom:20px;}.dashboard-inbox__heading > :last-child{flex-shrink:0;}.dashboard-inbox__heading a,.dashboard-action{color:var(--color-primary-element);font-weight:600;text-decoration:underline;white-space:nowrap;}.dashboard-table{overflow-x:auto;}table{border-collapse:collapse;width:100%;}th,td{text-align:start;padding:15px 12px;border-bottom:1px solid var(--color-border);vertical-align:top;}th{background:var(--color-background-hover);white-space:nowrap;}small{display:block;margin-top:6px;color:var(--color-text-maxcontrast);}.dashboard-campaign{color:var(--color-main-text);}.dashboard-status{display:inline-block;padding:4px 9px;border-radius:20px;background:var(--color-background-dark);font-size:13px;}.dashboard-empty{padding:36px 12px;text-align:center;color:var(--color-text-maxcontrast);}.dashboard-empty>span{display:inline-flex;}.dashboard-empty h4{font-size:17px;font-weight:600;margin-block:12px 6px;}.dashboard-pagination{display:flex;justify-content:space-between;align-items:center;margin-top:20px;}
.dashboard-shortcuts{margin-top:28px;}.dashboard-shortcuts>div{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px;}.dashboard-shortcuts a{display:flex;flex-direction:column;align-items:start;gap:10px;padding:20px;border:1px solid var(--color-border);border-radius:12px;text-decoration:none;}.dashboard-shortcuts a:hover{background:var(--color-background-hover);}.dashboard-shortcuts a>span:last-child{font-size:14px;color:var(--color-text-maxcontrast);line-height:1.5;}.dashboard-error{padding:16px;border:1px solid var(--color-border);border-inline-start:5px solid var(--color-error);border-radius:10px;margin-bottom:20px;}
@media(max-width:1000px){.dashboard-metrics{grid-template-columns:repeat(2,minmax(0,1fr));}}@media(max-width:767px){.signing-dashboard{padding:20px 12px;}.dashboard-metrics{gap:10px;}.dashboard-metrics button{padding:14px;min-height:126px;}.dashboard-inbox{padding:16px 12px;}.dashboard-inbox__heading{flex-direction:column;gap:8px;}header{gap:12px;flex-wrap:wrap;}.dashboard-header-actions{justify-content:flex-start;}h2{font-size:24px;}}
</style>
